#include <stdio.h>

int main(void)
{
    int seats = 6;
    char zone = 'A';
    double time = 1.5;
    printf("%c: %d / %.1f h\n", zone, seats, time);
    seats = seats + 2;
    printf("%c: %d / %.1f h\n", zone, seats, time);
    return 0;
}

