#include <stdio.h>

int main(void)
{
    int boxes = 12;
    char lane = 'B';
    double period = 0.5;
    printf("%c: %d / %.1f h\n", lane, boxes, period);
    boxes = boxes - 3;
    printf("%c: %d / %.1f h\n", lane, boxes, period);
    return 0;
}

